<?php
namespace App\Models;use App\Casts\DateOnly;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides expense claim item behavior within the WorkIntel application. */ class ExpenseClaimItem extends Model{protected $fillable=['expense_claim_id','expense_date','category','description','amount','tax_amount','currency','merchant','mileage_km','mileage_rate','project_id','cost_center_id','receipt_path','receipt_file_name','receipt_mime_type','receipt_size_bytes','receipt_sha256','metadata'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['expense_date'=>DateOnly::class,'amount'=>'decimal:2','tax_amount'=>'decimal:2','mileage_km'=>'decimal:2','mileage_rate'=>'decimal:3','metadata'=>'array'];}/** Handles the claim operation for the current WorkIntel workflow. */ public function claim():BelongsTo{return $this->belongsTo(ExpenseClaim::class,'expense_claim_id');}}
